 "content": "def transform(grid):
    """Project terminal endpoints of same-color edge bars inward as color-2 lines."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    bars = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 2, 6) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc)); stack.append((nr,nc))
            if len(comp) < 2:
                continue
            rows = [p[0] for p in comp]; cols = [p[1] for p in comp]
            horizontal = len(set(rows)) == 1
            vertical = len(set(cols)) == 1
            if horizontal and len(comp) == max(cols)-min(cols)+1:
                bars.append(("h", max(cols), rows[0]))
            elif vertical and len(comp) == max(rows)-min(rows)+1:
                bars.append(("v", max(rows), cols[0]))
    lines = set()
    for orient, endpoint, fixed in bars:
        if orient == "h":
            lines.update((r, endpoint) for r in range(h))
        else:
            lines.update((endpoint, c) for c in range(w))
    for r, c in lines:
        out[r][c] = 4 if grid[r][c] == 2 else 2
    return out
",
 "cross_profile": false
}

