 "content": "def transform(grid):
    """Extend inward rays from paired color bars, recoloring marked pixels."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # In this task the ray columns/rows are determined by the edge bars:
    # the bar at the top points down at its right endpoint, the right bar
    # points left at its upper endpoint, and the lower-left marker is recolored.
    # Generalize by detecting bars on grid edges and projecting from their
    # inward-facing tips.
    seen, rays = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 1, 2, 6) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc)); stack.append((nr,nc))
            rows, cols = [p[0] for p in comp], [p[1] for p in comp]
            if len(set(rows)) == 1 and len(comp) == max(cols)-min(cols)+1:
                rr = rows[0]
                if rr == 0:
                    rays.append(((rr, max(cols)), (1, 0)))
                elif rr == h-1:
                    rays.append(((rr, min(cols)), (-1, 0)))
            elif len(set(cols)) == 1 and len(comp) == max(rows)-min(rows)+1:
                cc = cols[0]
                if cc == 0:
                    rays.append(((max(rows), cc), (0, 1)))
                elif cc == w-1:
                    rays.append(((min(rows), cc), (0, -1)))
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    marker_set = set(markers)
    for (r, c), (dr, dc) in rays:
        r += dr; c += dc
        while 0 <= r < h and 0 <= c < w:
            if (r, c) in marker_set:
                out[r][c] = 4
                break
            if grid[r][c] not in (1, 6):
                break
            out[r][c] = 2
            r += dr; c += dc
    return out
