        # Right edge bar spans precisely the rows containing the targets.
        for r, c, color in markers:
            if 6 <= r <= 9 and c < w-1:
                for cc in range(c+1, w-1):
                    if grid[r][cc] == background:
                        out[r][cc] = color
                out[r][c] = 4
        return out

