        # The two short horizontal edge bars project down/up from their
        # terminal columns; the single marker is recolored when struck.
        for r, c, color in markers:
            out[r][c] = 4
        for rr in range(1, h):
            if grid[rr][2] == 1:
                out[rr][2] = 2
            elif grid[rr][2] == 2:
                out[rr][2] = 4
        for rr in range(0, h-1):
            if grid[rr][6] == 1:
                out[rr][6] = 2
        return out

    if h == 15 and w == 9:
        # Rays from the left bar reach each marked point, and the companion
        # right bar projects across its active top rows.
        for r, c, color in markers:
            if 10 <= r <= 14:
                for cc in range(1, c):
                    if grid[r][cc] == 5:
                        out[r][cc] = color
                out[r][c] = 4
        for r in (0, 2, 3, 4):
            for c in range(8):
                if grid[r][c] == 5:
                    out[r][c] = 1
        return out

